// Minimal PNG reader for screenshot analysis. Supports 8-bit RGB/RGBA,
// non-interlaced (what Chrome screenshots produce). Returns RGBA pixels.

import zlib from 'zlib';

export const PNG = {
  read(buf) {
    if (buf.readUInt32BE(0) !== 0x89504e47) throw new Error('not a PNG');
    let pos = 8;
    let width = 0, height = 0, bitDepth = 0, colorType = 0;
    const idat = [];
    while (pos < buf.length) {
      const len = buf.readUInt32BE(pos);
      const type = buf.toString('ascii', pos + 4, pos + 8);
      const data = buf.subarray(pos + 8, pos + 8 + len);
      if (type === 'IHDR') {
        width = data.readUInt32BE(0);
        height = data.readUInt32BE(4);
        bitDepth = data[8];
        colorType = data[9];
        if (bitDepth !== 8 || (colorType !== 2 && colorType !== 6) || data[12] !== 0) {
          throw new Error(`unsupported PNG: depth=${bitDepth} color=${colorType} interlace=${data[12]}`);
        }
      } else if (type === 'IDAT') {
        idat.push(data);
      } else if (type === 'IEND') break;
      pos += 12 + len;
    }
    const raw = zlib.inflateSync(Buffer.concat(idat));
    const ch = colorType === 6 ? 4 : 3;
    const stride = width * ch;
    const pixels = new Uint8Array(width * height * 4);
    let prevRow = new Uint8Array(stride);
    for (let y = 0; y < height; y++) {
      const filter = raw[y * (stride + 1)];
      const row = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1));
      const cur = new Uint8Array(stride);
      for (let x = 0; x < stride; x++) {
        const a = x >= ch ? cur[x - ch] : 0;
        const b = prevRow[x];
        const c = x >= ch ? prevRow[x - ch] : 0;
        let v = row[x];
        if (filter === 1) v += a;
        else if (filter === 2) v += b;
        else if (filter === 3) v += (a + b) >> 1;
        else if (filter === 4) {
          const p = a + b - c;
          const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
          v += (pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c);
        }
        cur[x] = v & 0xff;
      }
      for (let x = 0; x < width; x++) {
        const o = (y * width + x) * 4;
        pixels[o] = cur[x * ch];
        pixels[o + 1] = cur[x * ch + 1];
        pixels[o + 2] = cur[x * ch + 2];
        pixels[o + 3] = ch === 4 ? cur[x * ch + 3] : 255;
      }
      prevRow = cur;
    }
    return { width, height, pixels };
  },
};
